// English help – same sections/ids/pictures as static/hilfe.js
const K = (t) => `<kbd>${t}</kbd>`;
const HILFE = [
  ['start', 'Getting started', ['dashboard'], `
    <p>The <b>Command Center</b> manages your Linux server in the browser: load, Docker, virtual machines, terminal,
    users and security – in one place, light and dark, on the phone as on the PC.</p>
    <ul>
      <li><b>Sign in</b> with a Linux user of the server (or an own Command Center password, see “My account”).</li>
      <li><b>Navigation:</b> sidebar on the left (at the bottom on phones), ${K('⌘/Ctrl')} + ${K('K')} opens “Jump to …” for pages, containers and services.</li>
      <li><b>What you see depends on your permissions.</b> Superadmins see everything, everyone else only the pages of their groups.</li>
      <li><b>Help for the current page:</b> key ${K('?')}.</li>
      <li><b>Language:</b> Settings → Language (also on the sign-in page): Deutsch, English, Español. Your account remembers it on all devices.</li>
    </ul>`],
  ['uebersicht', 'Overview', ['dashboard'], `
    <p>Key figures (CPU, memory, network, disks) with a mini history and, below, graphs of the last 15 minutes up to 24 hours.</p>
    <ul><li>Graphs: pointing shows values, dragging zooms, the legend hides series, “Table” shows the numbers.</li>
    <li>Tapping a tile jumps to the matching graph.</li></ul>`, 'uebersicht'],
  ['system', 'Processes, services, updates', ['processes', 'services', 'updates'], `
    <ul><li><b>Processes:</b> sortable, kill a process (permission “End processes”).</li>
    <li><b>Services:</b> search, start, stop and restart systemd services.</li>
    <li><b>Updates:</b> pending package updates, installed on request.</li></ul>`],
  ['terminal', 'Terminal & tabs', ['terminal'], `
    <p>A real shell on the server. Every tab is its own session that <b>keeps running</b> – even if you close the page
    or the Command Center restarts – until you close the tab or type ${K('exit')}.</p>
    <table><tr><td>${K('Alt')} + ${K('T')}</td><td>new terminal</td></tr>
    <tr><td>${K('Alt')} + ${K('1')}…${K('9')}</td><td>switch to tab 1–9</td></tr>
    <tr><td>${K('Alt')} + ${K('⇧')} + ${K('←/→')}</td><td>move the active tab</td></tr>
    <tr><td>Double-click / right-click / ⋯</td><td>settings: name, pin, position, close</td></tr>
    <tr><td>Middle-click</td><td>close tab</td></tr></table>
    <ul><li><b>Pin:</b> the tab stays at the front and has no ×.</li>
    <li><b>Drag</b> to move tabs; the button next to “+” puts the tabs <b>on the side</b> (saved per user).</li>
    <li><b>Anyone who is not a superadmin</b> gets the shell as their own Linux user – without <code>sudo</code>/<code>su</code> (technically blocked).</li>
    <li>Copy: ${K('Ctrl')} + ${K('⇧')} + ${K('C')}, paste: ${K('Ctrl')} + ${K('⇧')} + ${K('V')}.</li></ul>`],
  ['docker', 'Docker', ['docker', 'docker-detail'], `
    <ul><li><b>Containers:</b> status, live CPU/RAM, start/stop/restart, logs (live), console, files, processes, inspect.</li>
    <li><b>Opening a container</b> shows four live tiles at the top (every second) and graphs of the last 5 minutes in the “Stats” tab.</li>
    <li><b>Images, networks, volumes, stacks</b> (Compose projects), <b>system</b> (storage, clean-up).</li>
    <li>Permissions: “View Docker”, “Start/stop containers”, “Manage Docker” (⚠ equals root).</li></ul>`, 'docker'],
  ['vms', 'Virtual machines', ['vms', 'vm-detail'], `
    <p>libvirt/KVM: create and start VMs, console in the browser (VNC/SPICE), snapshots, devices, networks, ISOs.
    Users with the permission “Own virtual machines” only see and operate their own VMs (name starts with their prefix) and shared ones.
    Without libvirt on the server the page stays empty – everything else works normally.</p>`],
  ['zugriff', 'Connections & browser', ['connections', 'browser'], `
    <ul><li><b>Connections:</b> save SSH/VNC/RDP to other machines and open them in the browser.</li>
    <li><b>Browser:</b> isolated browser sessions in a container – e.g. for sites you don't want to open in your own browser.</li></ul>`],
  ['sicherheit', 'Security & bans', ['security'], `
    <ul><li><b>IDS guard</b> (Suricata): traffic, hits, latest bans – live.</li>
    <li><b>Banned IPs:</b> from fail2ban, the IDS and by hand; ban/unban (several at once too), a ban applies at the firewall and – if set up – at the Cloudflare edge.</li>
    <li><b>Messages:</b> failed attempts, bans, logins – filter by application, source, text.</li>
    <li>Which parts run is chosen during installation (modules, see Frequently asked questions). Without fail2ban the IDS bans by itself.</li></ul>`, 'sicherheit'],
  ['angriffe', 'Attacks (attack radar)', ['angriffe'], `
    <p>Collects attack attempts every 2 minutes: searches for secrets (<code>.env</code>, <code>.git</code> …), vulnerability scans and
    exploits, wrong logins and IDS hits – 24 h / 7 / 30 days, origin, targets, searched paths.</p>
    <ul><li><b>Automatic ban</b> (with fail2ban): 3 scans within an hour or 1 exploit attempt → banned (1 day, longer on repeat).</li>
    <li>Normal traffic is not stored, only attempts (90 days).</li></ul>`, 'angriffe'],
  ['benutzer', 'Users, groups & permissions', ['users'], `
    <p>You grant permissions through <b>groups</b>; a user can be in several. The “Overview” view shows as a table who may do what.</p>
    <ul><li><b>24 permissions</b> in five areas; those marked ⚠ are critical (practically root or access to secrets).</li>
    <li><b>Templates:</b> observer, Docker caretaker, Docker admin, system admin, security, VM user, user care, tools, vault, “All signed-in users”.</li>
    <li><b>Passwords of other users</b> are set only by the <b>owner</b> (one designated superadmin).</li>
    <li>“User care” may only assign groups whose permissions it has itself. Service accounts of programs are protected.</li>
    <li>The server checks every permission on every action – the menu only hides things.</li></ul>`, 'benutzer'],
  ['benachrichtigungen', 'Notifications', ['notifications'], `<p>Messages from ntfy (e.g. bans, logins, server warnings) to read later.</p>`],
  ['werkzeuge', 'Optional pages', ['konten', 'codes', 'backups', 'werkzeuge', 'startseite', 'automationen'], `
    <p>Accounts, codes, backups, IT tools, My dashboard and automations only exist when the server lists them in
    <code>funktionen.json</code>. Embedded apps run in a sandbox without access to the Command Center.</p>`],
  ['einstellungen', 'Settings, license & my account', ['settings', 'konto'], `
    <ul><li><b>Language</b> and appearance (light/dark).</li>
    <li><b>License</b> (superadmins): status, valid until, enter a new key. If it expires soon, a notice appears at the top.</li>
    <li><b>Visible tabs:</b> hide pages from your own sidebar (permissions do not change).</li>
    <li><b>Default SSH access</b> for connections. <b>Database:</b> state of the fast cache (PostgreSQL with replica, fallback SQLite).</li>
    <li><b>My account:</b> profile picture, change password, email for “Forgot password?”, sign out on all other devices.</li></ul>`, 'einstellungen'],
  ['tasten', 'All keyboard shortcuts', [], `
    <table><tr><td>${K('⌘/Ctrl')} + ${K('K')}</td><td>Jump to … (pages, containers, services, actions)</td></tr>
    <tr><td>${K('⌘/Ctrl')} + ${K('B')}</td><td>collapse/expand sidebar</td></tr>
    <tr><td>${K('?')}</td><td>help for the current page</td></tr>
    <tr><td>${K('Alt')} + ${K('T')} / ${K('1')}…${K('9')}</td><td>terminal: new tab / switch tab</td></tr>
    <tr><td>${K('Esc')}</td><td>close windows and search</td></tr></table>`],
  ['faq', 'Frequently asked questions', [], `
    <details><summary>How do I update the Command Center?</summary><p>On the server: <code>sudo command-center update</code>. Settings, users and data stay. A valid license is required.</p></details>
    <details><summary>How do I change what is installed (fail2ban, IDS, backup …)?</summary><p><code>sudo command-center module</code> shows the modules, <code>sudo command-center module +postgres -ids</code> adds PostgreSQL and removes the IDS. Modules: fail2ban, ids, firewall, radar, cloudflare, ntfy, postgres, backup. The IDS also works without fail2ban – it then bans by itself.</p></details>
    <details><summary>I locked myself out (my IP is banned).</summary><p>Sign in from another connection (e.g. phone without Wi-Fi) and use “Unban my IP” under <b>Security &amp; bans</b> – or via SSH: <code>sudo waechter freigeben &lt;IP&gt;</code>. To prevent it: add your own IPs to <code>TRUSTED_IPS</code> in <code>/etc/linux-dashboard/schutz.conf</code>.</p></details>
    <details><summary>I forgot my password.</summary><p>Use “Forgot password?” on the sign-in page (needs a confirmed email under “My account”). Otherwise via SSH: <code>sudo passwd &lt;user&gt;</code>. In the Command Center only the owner sets other users' passwords.</p></details>
    <details><summary>How do I make the Command Center reachable from outside safely?</summary><p>Never expose it unprotected – it has root rights. Easiest via VPN (Tailscale, WireGuard) or an HTTPS reverse proxy or Cloudflare Tunnel with access protection. Who may connect directly is set in <code>/etc/linux-dashboard/dashboard.env</code> (<code>DASHBOARD_ALLOWED_NETS</code>).</p></details>
    <details><summary>Where do I see my license and what happens when it expires?</summary><p>Under <b>Settings → License</b> (or <code>sudo command-center lizenz</code>). A notice appears 30 days before. After expiry the Command Center keeps running, but updates are blocked until you renew: enter a new key under Settings. Request and renew: <a href="https://lizenz.slxt.dev" target="_blank" rel="noopener">lizenz.slxt.dev</a>.</p></details>
    <details><summary>How do I back up and restore my data?</summary><p>With the <b>backup</b> module the server saves settings and data every night to <code>/var/backups/command-center</code> (14 days). By hand: <code>sudo command-center backup</code>, list: <code>… backup --liste</code>, restore: <code>… backup --zurueck &lt;file&gt;</code>.</p></details>
    <details><summary>Why doesn't <code>sudo</code> work in the terminal?</summary><p>Anyone who is not a superadmin deliberately gets a shell without root rights. Superadmins are set by <code>DASH_SUPERADMINS</code> in <code>/etc/linux-dashboard/dashboard.env</code>.</p></details>
    <details><summary>How many resources does the Command Center need?</summary><p>The Command Center itself about 100–200 MB RAM. The IDS (Suricata) needs 1–2 GB – with little RAM, leave out the <b>ids</b> module.</p></details>
    <details><summary>Where are settings and data stored?</summary><p>Settings: <code>/etc/linux-dashboard/</code> (<code>dashboard.env</code>, <code>schutz.conf</code>, <code>module.conf</code>). Data: <code>/var/lib/linux-dashboard/</code>. Program: <code>/opt/command-center</code>.</p></details>
    <details><summary>How do I remove the Command Center?</summary><p><code>sudo command-center deinstallieren</code> – data stays; with <code>--alles</code> data, settings and the protection package (fail2ban/IDS/firewall) go too.</p></details>`],
  ['probleme', 'When something does not work', [], `
    <ul><li><b>“You lack the permission …”</b> – a superadmin can grant it to you under Users → Groups.</li>
    <li><b>Page does not load / old view:</b> reload (${K('⌘/Ctrl')} + ${K('⇧')} + ${K('R')}).</li>
    <li><b>Terminal disconnected:</b> “New” reconnects – the session keeps running.</li>
    <li><b>Database “SQLite” instead of PostgreSQL:</b> the database container is not reachable; everything keeps working, status under Settings.</li>
    <li><b>Logs:</b> <code>sudo command-center logs -f</code>; state: <code>sudo command-center status</code>.</li></ul>`],
];

d.hilfe = HILFE;
window.CC_SPRACHE_LADEN(d);
